import com.google.common.base.Charsets;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.runners.MockitoJUnitRunner;
import org.stellar.sdk.xdr.PublicKey;
import org.stellar.sdk.xdr.SignerKey;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class KeyPairTest {

    @Test
    public void fromSecretSeedCharArrayTest() {
        String seed = "S5EDGEDVHFXOYASZGIVRGI5RHFPBLQF7XHGBMHZIDO24MBPIXMYHUQL7";
        KeyPair keyPair = KeyPair.fromSecretSeed(seed.toCharArray());

        assertNotNull(keyPair);
        assertTrue(keyPair.canSign());
    }

    @Test
    public void fromSecretSeedStringTest() {
        String seed = "S5EDGEDVHFXOYASZGIVRGI5RHFPBLQF7XHGBMHZIDO24MBPIXMYHUQL7";
        KeyPair keyPair = KeyPair.fromSecretSeed(seed);

        assertNotNull(keyPair);
        assertTrue(keyPair.canSign());
    }

    @Test(expected = RuntimeException.class)
    public void fromSecretSeedBytesTest() {
        byte[] seed = "*".getBytes();
        KeyPair keyPair = KeyPair.fromSecretSeed(seed);
    }

    @Test
    public void fromPublicBytesTest() {
        KeyPair oldPair = KeyPair.random();
        byte[] publicKey = oldPair.getPublicKey();
        KeyPair newPair = KeyPair.fromPublicKey(publicKey);

        assertEquals(oldPair.getPublicKey(), newPair.getPublicKey());
    }

    @Test
    public void getXdrPublicKeyTest() {
        KeyPair keyPair = KeyPair.random();
        PublicKey publicKey = keyPair.getXdrPublicKey();

        assertNotNull(publicKey);
        assertNull(publicKey.getEd25519());
    }

    @Test
    public void getXdrSignerKeyTest() {
        KeyPair keyPair = KeyPair.random();
        SignerKey signerKey = keyPair.getXdrSignerKey();

        assertNotNull(signerKey);
        assertNotNull(signerKey.getEd25519());
    }

    @Test
    public void verifyTest() {
        KeyPair keyPair = KeyPair.random();
        String data = "Hello, Stellar!";
        byte[] signature = keyPair.sign(data.getBytes(Charsets.UTF_8));

        assertTrue(keyPair.verify(data.getBytes(Charsets.UTF_8), signature));
    }

    @Test
    public void equalsTest() {
        KeyPair keyPair1 = KeyPair.fromSecretSeed("S5EDGEDVHFXOYASZGIVRGI5RHFPBLQF7XHGBMHZIDO24MBPIXMYHUQL7");
        KeyPair keyPair2 = KeyPair.fromSecretSeed("S5EDGEDVHFXOYASZGIVRGI5RHFPBLQF7XHGBMHZIDO24MBPIXMYHUQL7");

        assertEquals(keyPair1, keyPair2);
    }

    @Test
    public void hashCodeTest() {
        KeyPair keyPair1 = KeyPair.fromSecretSeed("S5EDGEDVHFXOYASZGIVRGI5RHFPBLQF7XHGBMHZIDO24MBPIXMYHUQL7");
        KeyPair keyPair2 = KeyPair.fromSecretSeed("S5EDGEDVHFXOYASZGIVRGI5RHFPBLQF7XHGBMHZIDO24MBPIXMYHUQL7");

        assertEquals(keyPair1.hashCode(), keyPair2.hashCode());
    }
}
